"""Deliberately buggy demo: normalized duplicate SKUs silently overwrite."""


def total_by_sku(items):
    normalized = {}
    for sku, quantity in items:
        canonical_sku = sku.strip().upper()
        if canonical_sku in normalized:
            raise ValueError("duplicate canonical SKU: {}".format(canonical_sku))
        normalized[canonical_sku] = quantity
    return sum(normalized.values())
